//! Release check, documentation: every method the node serves has an entry in
//! `docs/RPC.md`, and every MCP tool it serves has one in `docs/MCP.md`.
//!
//! Both files are generated by `scripts/gen-api-docs.py` from the same source
//! this test reads: the method tables in `rpc_gates.rs`, the typed tools in
//! `mcp/server.rs` and the mirror table in `mcp/rpc_tools.rs`. A new method or
//! tool without a regenerated reference fails here, and so does an entry for
//! one that is gone. The CLI reference has its own gate
//! (`cli_documentation_tests` in tenzro-cli).

#[path = "support/gate.rs"]
mod gate;

use std::collections::BTreeSet;

fn read(rel: &str) -> String {
    std::fs::read_to_string(gate::repo_root().join(rel)).unwrap_or_else(|e| panic!("{rel}: {e}"))
}

/// The names under `### ` headings, written as `` ### `name` ``.
fn headings(doc: &str) -> BTreeSet<String> {
    doc.lines()
        .filter_map(|l| l.strip_prefix("### `"))
        .filter_map(|l| l.strip_suffix('`'))
        .map(str::to_string)
        .collect()
}

/// The body of each `### ` entry, keyed by name.
fn entries(doc: &str) -> Vec<(String, String)> {
    let mut out: Vec<(String, String)> = Vec::new();
    let mut open = false;
    for line in doc.lines() {
        if let Some(name) = line.strip_prefix("### `").and_then(|l| l.strip_suffix('`')) {
            out.push((name.to_string(), String::new()));
            open = true;
        } else if line.starts_with("## ") {
            open = false;
        } else if open && let Some(last) = out.last_mut() {
            last.1.push_str(line);
            last.1.push('\n');
        }
    }
    out
}

/// MCP tool names: the typed tools (the function after each `#[tool(`
/// attribute, or its `name = "..."`) and the mirror rows.
fn mcp_tools() -> BTreeSet<String> {
    let server = gate::before_tests(&read("crates/tenzro-node/src/mcp/server.rs"));
    let mut out = BTreeSet::new();
    let mut offset = 0usize;
    for line in server.split_inclusive('\n') {
        let start = offset;
        offset += line.len();
        if !line.trim_start().starts_with("#[tool(") {
            continue;
        }
        let after = &server[start..];
        let fn_at = after
            .find("async fn ")
            .expect("a #[tool] attribute precedes a function");
        let attr = &after[..fn_at];
        let name = match attr.find("name = \"") {
            Some(n) => attr[n + 8..]
                .split('"')
                .next()
                .unwrap_or_default()
                .to_string(),
            None => after[fn_at + 9..]
                .split(|c: char| !(c.is_ascii_alphanumeric() || c == '_'))
                .next()
                .unwrap_or_default()
                .to_string(),
        };
        out.insert(name);
    }
    let mirror = read("crates/tenzro-node/src/mcp/rpc_tools.rs");
    for line in gate::before_tests(&mirror).lines() {
        if let Some(v) = line.trim().strip_prefix("name: \"") {
            out.insert(v.split('"').next().unwrap_or_default().to_string());
        }
    }
    out
}

fn assert_same(kind: &str, file: &str, served: &BTreeSet<String>, documented: &BTreeSet<String>) {
    let missing: Vec<_> = served.difference(documented).collect();
    let stale: Vec<_> = documented.difference(served).collect();
    assert!(
        missing.is_empty() && stale.is_empty(),
        "{file} is out of date (run scripts/gen-api-docs.py): {} {kind} served but undocumented {missing:?}; {} documented but not served {stale:?}",
        missing.len(),
        stale.len()
    );
}

#[test]
fn every_served_method_has_a_reference_entry() {
    let methods = gate::rpc_methods();
    assert!(
        methods.len() > 400,
        "read only {} methods from rpc_gates.rs",
        methods.len()
    );
    assert_same(
        "method(s)",
        "docs/RPC.md",
        &methods,
        &headings(&read("docs/RPC.md")),
    );
}

#[test]
fn every_reference_entry_has_access_params_returns_errors_and_an_example() {
    let doc = read("docs/RPC.md");
    let incomplete: Vec<String> = entries(&doc)
        .into_iter()
        .filter(|(_, body)| {
            ![
                "**Access.**",
                "**Params.**",
                "**Returns.**",
                "**Errors.**",
                "**Example.**",
                "```json",
            ]
            .iter()
            .all(|s| body.contains(s))
        })
        .map(|(name, _)| name)
        .collect();
    assert!(
        incomplete.is_empty(),
        "docs/RPC.md entries missing a section: {incomplete:?}"
    );
}

#[test]
fn every_served_mcp_tool_has_a_reference_entry() {
    let tools = mcp_tools();
    assert!(tools.len() > 300, "read only {} MCP tools", tools.len());
    assert_same(
        "tool(s)",
        "docs/MCP.md",
        &tools,
        &headings(&read("docs/MCP.md")),
    );
}
